import TurndownService from 'turndown';

import { removeLineBreaks } from 'proton-mail/helpers/string';
import { extractContentFromPtag, prepareConversionToHTML } from 'proton-mail/helpers/textToHtml';

const turndownService = new TurndownService({
    bulletListMarker: '-', // Use '-' instead of '*'
    hr: '---', // Use '---' instead of '***'
    headingStyle: 'atx', // Use '#' for headings
});

turndownService.addRule('strikethrough', {
    filter: ['del', 's', 'strike' as any], // 'strike' is deprecated, however the editor insert strike tag
    replacement: function (content) {
        return `~~${content}~~`;
    },
});

// Markdown has no syntax for these attributes. Keep formatted links and images as
// inline HTML so the attributes survive the model round trip.
turndownService.addRule('formatted-link', {
    filter: (node) => node.nodeName === 'A' && (node.hasAttribute('class') || node.hasAttribute('style')),
    replacement: (_content, node) => (node as HTMLElement).outerHTML,
});

turndownService.addRule('formatted-image', {
    filter: (node) => node.nodeName === 'IMG' && (node.hasAttribute('class') || node.hasAttribute('style')),
    replacement: (_content, node) => (node as HTMLElement).outerHTML,
});

const cleanMarkdown = (markdown: string): string => {
    const lines = markdown.split('\n');
    const listIndentations = lines
        .map((line) => /^(\s*)(?:[-+*]|\d+[.)])\s/.exec(line)?.[1].length)
        .filter((indentation): indentation is number => indentation !== undefined);
    const baseListIndentation = listIndentations.length ? Math.min(...listIndentations) : 0;

    return lines
        .map((line) => {
            const listItem = /^(\s*)(?=(?:[-+*]|\d+[.)])\s)/.exec(line);
            if (listItem && baseListIndentation) {
                return line.slice(Math.min(baseListIndentation, listItem[1].length));
            }
            return line.replace(/^[ \t]+(?=(?:#{1,6}\s|>\s?|```|~~~))/, '');
        })
        .join('\n');
};

export const fixNestedLists = (dom: Document): Document => {
    dom.querySelectorAll('ul, ol').forEach((list) => {
        Array.from(list.children).forEach((child) => {
            const tag = child.tagName.toLowerCase();
            if ((tag === 'ul' || tag === 'ol') && child.previousElementSibling?.tagName.toLowerCase() === 'li') {
                child.previousElementSibling.appendChild(child);
            } else if (tag === 'ul' || tag === 'ol') {
                const li = dom.createElement('li');
                list.insertBefore(li, child);
                li.appendChild(child);
            }
        });
    });
    return dom;
};

export const htmlToMarkdown = (dom: Document): string => {
    const markdown = turndownService.turndown(fixNestedLists(dom));
    const markdownCleaned = cleanMarkdown(markdown);
    return markdownCleaned;
};

// Using the same config and steps than what we do in textToHTML.
// This is formatting lists and other elements correctly, adding line separators etc...
export const markdownToHTML = (markdownContent: string, keepLineBreaks = false, disabledRules?: string[]): string => {
    const html = prepareConversionToHTML(markdownContent, disabledRules);
    // Need to remove line breaks, we already have <br/> tag to separate lines
    const htmlCleaned = keepLineBreaks ? html : removeLineBreaks(html);
    /**
     * The capturing group includes negative lookup "(?!<p>)" in order to avoid nested problems.
     * Ex, this capture will be ignored : "<p>Hello</p><p>Hello again</p>""
     * Because it would have ended up with this result : "Hello</p><p>Hello again"
     */
    return extractContentFromPtag(htmlCleaned) || htmlCleaned;
};
